import re
files=["AlgebraicJacobian/Picard/FGAPicRepresentability.lean","AlgebraicJacobian/Picard/PicEtSubcanonical.lean","AlgebraicJacobian/Picard/PicEtSeparated.lean","AlgebraicJacobian/Picard/Pic0Et.lean","AlgebraicJacobian/Picard/PicEtDescentAssembly.lean","AlgebraicJacobian/Picard/Pic0EtTangentSpace.lean"]
pat=re.compile(r'^\s*(@\[[^\]]*\]\s*)?(private |protected |noncomputable |scoped )*(instance|theorem|lemma|def|abbrev)\b')
for f in files:
    lines=open(f).read().split("\n")
    # mask docstrings
    masked=[];indoc=False
    for l in lines:
        if indoc:
            masked.append(''); 
            if '-/' in l: indoc=False
            continue
        if re.search(r'/-',l) and '-/' not in l:
            indoc=True; masked.append(''); continue
        if re.match(r'\s*/-.*-/\s*$',l): masked.append(''); continue
        masked.append(re.sub(r'--.*$','',l))
    for i,l in enumerate(masked):
        if pat.match(l):
            # collect until next decl or blank-then-decl
            blk=[]
            j=i
            while j<len(masked):
                blk.append((j+1,masked[j]))
                j+=1
                if j<len(masked) and pat.match(masked[j]): break
                if j-i>40: break
            body="\n".join(b[1] for b in blk)
            if re.search(r'choose_spec|\.choose\b|Classical\.choice|HasSmoothProperQuotient\.is_representable|has_pic_scheme|has_representable|locallyOfFiniteType\b\s*$|HasAbelMap\.abel|has_div_functor',body):
                print("="*72)
                print(f,"line",i+1)
                for bl,bs in blk:
                    if bs.strip(): print(f"  {bl}: {bs}")
